import{_ as r,C as o,o as n,c as d,j as a,a as t,b as l,w as i,E as g,a8 as h,a9 as m}from"./chunks/framework.BOiBTRPC.js";const k=JSON.parse('{"title":"System Design for Data Engineers","description":"The distributed-systems and pipeline-design fundamentals that senior data engineers are interviewed on and paged for — CAP, idempotency, fault tolerance, and ML system design.","frontmatter":{"title":"System Design for Data Engineers","description":"The distributed-systems and pipeline-design fundamentals that senior data engineers are interviewed on and paged for — CAP, idempotency, fault tolerance, and ML system design."},"headers":[],"relativePath":"system-design/index.md","filePath":"system-design/index.md"}'),p={name:"system-design/index.md"};function c(u,e,f,y,b,w){const s=o("Mermaid");return n(),d("div",null,[e[1]||(e[1]=a("h1",{id:"system-design-for-data-engineers",tabindex:"-1"},[t("System Design for Data Engineers "),a("a",{class:"header-anchor",href:"#system-design-for-data-engineers","aria-label":'Permalink to "System Design for Data Engineers"'},"​")],-1)),e[2]||(e[2]=a("blockquote",null,[a("p",null,[a("strong",null,"Why it matters"),t(" — At senior level nobody asks you to recite syntax. They ask: "),a("em",null,'"Design a system that ingests 50k events/sec, survives a region failure, and never double-charges a customer."'),t(" This track is the vocabulary and the trade-off intuition for answering that.")])],-1)),e[3]||(e[3]=a("p",null,[a("strong",null,"Who this is for:"),t(" data engineers prepping for senior/staff system-design interviews, and engineers who own pipelines in production and want a sharper mental model of why things fail the way they do.")],-1)),(n(),l(h,null,{default:i(()=>[g(s,{id:"mermaid-11",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20A%5B%22Foundations%20%E2%80%94%20how%20distributed%20systems%20break%22%5D%20--%3E%20B%5B%22Pipeline%20design%20%E2%80%94%20how%20to%20build%20one%20that%20survives%22%5D%0A%20%20%20%20B%20--%3E%20C%5B%22ML%20systems%20%E2%80%94%20the%20same%20ideas%20applied%20to%20models%20and%20RAG%22%5D%0A%20%20%20%20C%20--%3E%20D%5B%22ML%20pipelines%20%E2%80%94%20how%20models%20get%20produced%2C%20gated%2C%20and%20shipped%22%5D%0A%20%20%20%20A%20-.-%3E%7C%22CAP%2C%20replication%2C%20partitioning%22%7C%20B%0A%20%20%20%20B%20-.-%3E%7C%22feature%20stores%2C%20serving%2C%20drift%22%7C%20C%0A%20%20%20%20C%20-.-%3E%7C%22validation%20gates%2C%20registries%2C%20CI%2FCD%22%7C%20D%0A"})]),fallback:i(()=>[...e[0]||(e[0]=[t(" Loading... ",-1)])]),_:1})),e[4]||(e[4]=m('<h2 id="chapters" tabindex="-1">Chapters <a class="header-anchor" href="#chapters" aria-label="Permalink to &quot;Chapters&quot;">​</a></h2><h3 id="data-intensive-foundations" tabindex="-1"><a href="/Data-Knowledge/system-design/data-intensive.html">Data-Intensive Foundations</a> <a class="header-anchor" href="#data-intensive-foundations" aria-label="Permalink to &quot;[Data-Intensive Foundations](/system-design/data-intensive)&quot;">​</a></h3><p>The Kleppmann frame — reliability, scalability, maintainability — then the machinery underneath every data system you operate: CAP and PACELC, consistency models, replication topologies and split-brain, partitioning and hot spots, isolation anomalies, consensus intuition via Raft, clocks and ordering, and how batch vs streaming read paths differ. This is the chapter that makes &quot;why did the warehouse show stale rows?&quot; a diagnosable question instead of a mystery.</p><h3 id="designing-reliable-pipelines" tabindex="-1"><a href="/Data-Knowledge/system-design/pipeline-design.html">Designing Reliable Pipelines</a> <a class="header-anchor" href="#designing-reliable-pipelines" aria-label="Permalink to &quot;[Designing Reliable Pipelines](/system-design/pipeline-design)&quot;">​</a></h3><p>The reference architecture — ingest → raw → curated → serve, wrapped in an observability plane — and every pattern that makes it survive production: idempotency keys and dedupe windows, why exactly-once is an illusion and what actually works, backpressure and load shedding, dead-letter queues, schema evolution and data contracts, checkpoint/restart and blue-green backfills, data SLOs, and a worked capacity-estimation example you can reuse verbatim in interviews.</p><h3 id="ml-genai-system-design" tabindex="-1"><a href="/Data-Knowledge/system-design/ml-systems.html">ML &amp; GenAI System Design</a> <a class="header-anchor" href="#ml-genai-system-design" aria-label="Permalink to &quot;[ML &amp; GenAI System Design](/system-design/ml-systems)&quot;">​</a></h3><p>The interview framework — requirements → data → features → model → serving → monitoring — then the parts data engineers actually own: feature stores and training-serving skew, batch vs real-time inference, model lifecycle and shadow deploys, drift monitoring, plus three worked designs: fraud detection under a latency budget, two-stage recommendation, and a full RAG/GenAI architecture with guardrails and cost controls.</p><h3 id="ml-training-pipelines-in-production" tabindex="-1"><a href="/Data-Knowledge/system-design/ml-pipelines.html">ML Training Pipelines in Production</a> <a class="header-anchor" href="#ml-training-pipelines-in-production" aria-label="Permalink to &quot;[ML Training Pipelines in Production](/system-design/ml-pipelines)&quot;">​</a></h3><p>The pipeline that produces the model, decomposed TFX-style: ExampleGen → StatisticsGen → SchemaGen → ExampleValidator → Transform → Trainer → Tuner → Evaluator → InfraValidator → Pusher, and why every gate exists. Data validation as a pipeline step with the three skews, feature engineering inside the pipeline via the shipped transform graph, model versioning and registry semantics, orchestration trade-offs (Beam, Kubeflow, managed, Airflow), the ML CI/CD test pyramid, and the monitoring hand-off that closes the retraining loop.</p><h3 id="genai-engineering" tabindex="-1"><a href="/Data-Knowledge/system-design/genai-engineering.html">GenAI Engineering</a> <a class="header-anchor" href="#genai-engineering" aria-label="Permalink to &quot;[GenAI Engineering](/system-design/genai-engineering)&quot;">​</a></h3><p>Chip Huyen&#39;s AI Engineering distilled for data engineers: evaluation-first development, prompts as versioned pipeline stages, RAG as a data-engineering problem (chunking, hybrid retrieval, reranking), the prompt → RAG → finetune decision tree, inference optimization (batching, KV cache, quantization, distillation), agent architectures, and token-budget cost engineering.</p><h3 id="data-platform-design-case-studies" tabindex="-1"><a href="/Data-Knowledge/system-design/platform-designs.html">Data Platform Design Case Studies</a> <a class="header-anchor" href="#data-platform-design-case-studies" aria-label="Permalink to &quot;[Data Platform Design Case Studies](/system-design/platform-designs)&quot;">​</a></h3><p>Five end-to-end designs that combine everything above: a greenfield lakehouse for a 50-team org, a real-time personalization and feature platform, a global metrics and semantic layer, a compliance-grade PII platform, and a legacy on-prem ETL → cloud lakehouse migration. Each case follows the same skeleton — capacity estimate, decision log, failure modes, and what changes at 10x — so you can reuse the structure in interviews and design docs.</p><h2 id="pareto-focus" tabindex="-1">Pareto focus <a class="header-anchor" href="#pareto-focus" aria-label="Permalink to &quot;Pareto focus&quot;">​</a></h2><p>The ideas in this track that carry the most weight:</p><ol><li><strong>There is no exactly-once delivery.</strong> Effective-once = at-least-once delivery + idempotent writes + dedupe. Design every sink for retries.</li><li><strong>CAP is a partition-time choice, not a global one.</strong> You pick CP or AP <em>per subsystem</em>; PACELC adds the healthy-network cost of that choice.</li><li><strong>Linearizability is expensive and often unnecessary.</strong> Know what each consistency/isolation level actually buys before paying for it.</li><li><strong>Hot keys beat any partition strategy.</strong> Hash vs range is table stakes; the celebrity problem is what takes systems down.</li><li><strong>Idempotency and schema contracts are the two highest-ROI reliability investments</strong> in any pipeline — ahead of any tool choice.</li><li><strong>Data SLOs are what make a pipeline a product.</strong> Freshness, completeness, correctness — measured, alerted, owned.</li><li><strong>In ML systems the model is ~10% of the design.</strong> Features, serving latency, drift monitoring, and rollback are the other 90%.</li><li><strong>RAG is a data-engineering problem.</strong> Ingestion, chunking, indexing, and evaluation discipline determine answer quality far more than model choice.</li><li><strong>A training pipeline is a data pipeline with extra gates.</strong> Data validation, transform reuse, per-slice eval, and infra validation stand between raw data and a deployed model; the metadata store is what makes any of it reproducible.</li></ol>',16))])}const C=r(p,[["render",c]]);export{k as __pageData,C as default};
